1	import type { Metadata } from "next";
2	import { notFound } from "next/navigation";
3	import { db } from "@/lib/db";
4	import { UseCaseLanding } from "@/components/marketing/UseCaseLanding";
5	import type { PlanCard } from "@/components/marketing/PricingGrid";
6	import { APP_URL, FaqJsonLd, ProductOffersJsonLd } from "@/components/marketing/StructuredData";
7	import { Section, SectionTitle } from "@/components/marketing/primitives";
8	import { GameLandingCombined } from "@/components/marketing/gamelanding/GameLandingCombined";
9	import type { PreviewGame } from "@/components/marketing/gamelanding/data";
10	import { ReviewBadges } from "@/components/marketing/ReviewBadges";
11	import Link from "next/link";
12	import {
13	  findCombo,
14	  buildLanding,
15	  findRegionCombo,
16	  buildRegionLanding,
17	  LANDING_SLUGS,
18	  REGION_LANDING_SLUGS,
19	  type LandingPlan,
20	  type BuiltLanding,
21	} from "@/lib/marketing/locationLandings";
22	import {
23	  findGameLocationCombo,
24	  buildGameLocationLanding,
25	  buildGameLocationPreviewGame,
26	  findGeneralLocationCombo,
27	  buildGeneralLocationLanding,
28	  GAME_LOCATION_SLUGS,
29	  GENERAL_LOCATION_SLUGS,
30	  type GamePlanRow,
31	} from "@/lib/marketing/gameLocationLandings";
32	
33	/**
34	 * Programmatic "(location) (service)" marketing landing pages, the region-tier
35	 * umbrella pages above them, AND (added here) the game-family × location
36	 * matrix + the general per-location VPS/Game-Server pages that don't already
37	 * exist via the tables above — see lib/marketing/gameLocationLandings.ts's
38	 * file doc for the full architecture note.
39	 *
40	 * Four data tables, one route: a slug is checked against the region matrix,
41	 * then the city matrix, then the game×location matrix, then the general
42	 * new-location matrix — in that order, so nothing here can ever shadow a
43	 * hand-written static marketing page (which wins at request time anyway) or
44	 * silently collide with an existing slug. Anything in none of the four falls
45	 * through to a 404. Real DB rows (VPS `Plan` or, for a game×location combo,
46	 * that family's real `GamePlan` rows) feed every page's pricing grid and
47	 * Product rich-result — nothing here is a hardcoded price.
48	 */
49	
50	export const dynamic = "force-dynamic";
51	
52	// Pre-declare every known slug across all four tables so Next can enumerate
53	// them at build time; unknown slugs are rejected in the page/metadata via
54	// notFound().
55	export function generateStaticParams(): Array<{ slug: string }> {
56	  return [...REGION_LANDING_SLUGS, ...LANDING_SLUGS, ...GAME_LOCATION_SLUGS, ...GENERAL_LOCATION_SLUGS].map((slug) => ({
57	    slug,
58	  }));
59	}
60	
61	async function loadVpsPlans(): Promise<LandingPlan[]> {
62	  return db.plan.findMany({
63	    where: { active: true },
64	    orderBy: { sortOrder: "asc" },
65	  });
66	}
67	
68	/**
69	 * Real, active `GamePlan` rows for one family, mapped both to the plain
70	 * `GamePlanRow[]` the copy builder reads for prose (RAM/slots/price only)
71	 * and to full `PlanCard[]` for the pricing grid — `bandwidthTB`/`storageTier`
72	 * come from each row's real `basePlan` (the actual VPS-grade Plan the game
73	 * server is provisioned on), never a fabricated number.
74	 */
75	async function loadGamePlans(gameFamily: string): Promise<{ rows: GamePlanRow[]; cards: PlanCard[] }> {
76	  const plans = await db.gamePlan.findMany({
77	    where: { gameFamily, active: true },
78	    orderBy: { sortOrder: "asc" },
79	    include: { basePlan: true },
80	  });
81	  const rows: GamePlanRow[] = plans.map((p) => ({
82	    id: p.id,
83	    name: p.name,
84	    ramMB: p.ramMB,
85	    slots: p.slots,
86	    priceCents: p.priceCents,
87	    introPriceCents: p.introPriceCents,
88	  }));
89	  const cards: PlanCard[] = plans.map((p) => ({
90	    id: p.id,
91	    name: p.name,
92	    cpuCores: p.cpuCores,
93	    ramMB: p.ramMB,
94	    diskGB: p.diskGB,
95	    bandwidthTB: p.basePlan.bandwidthTB,
96	    priceCents: p.priceCents,
97	    storageTier: p.basePlan.storageTier,
98	    introMonthlyCents: p.introPriceCents,
99	    slots: p.slots,
100	  }));
101	  return { rows, cards };
102	}
103	
104	/**
105	 * Discriminant is NOT "does this page's service key happen to be `game`" —
106	 * the pre-existing city/region/general-location "game server hosting" pages
107	 * (e.g. "toronto-game-server-hosting") already price themselves off generic
108	 * VPS `Plan` rows (same as every other service on those tables) and deploy
109	 * as `service=vps`, unchanged from before this file existed. Only a genuine
110	 * per-family combo (e.g. "singapore-minecraft-server-hosting", resolved via
111	 * `findGameLocationCombo`) prices off that family's real `GamePlan` rows and
112	 * needs `service="game"` + `gameFamily` wired through to the deploy links.
113	 */
114	type Resolved =
115	  | { kind: "generic"; built: BuiltLanding; plans: LandingPlan[] }
116	  | {
117	      kind: "game-family";
118	      built: BuiltLanding;
119	      plans: PlanCard[];
120	      gameFamily: string;
121	      productName: string;
122	      /**
123	       * The GameLandingCombined-ready merge (real pricing + this combo's
124	       * honesty framing over the game's PREVIEW_GAMES fixture) — see
125	       * lib/marketing/gameLocationLandings.ts's buildGameLocationPreviewGame
126	       * doc. `undefined` only if `family` somehow has no PREVIEW_GAMES entry
127	       * (shouldn't happen for anything in ACTIVE_GAME_FAMILIES), in which case
128	       * the page below falls back to the generic UseCaseLanding render so a
129	       * drift between the two lists degrades gracefully instead of 500ing.
130	       */
131	      previewGame: PreviewGame | undefined;
132	    };
133	
134	async function resolve(slug: string): Promise<Resolved | undefined> {
135	  const regionCombo = findRegionCombo(slug);
136	  if (regionCombo) {
137	    const plans = await loadVpsPlans();
138	    return { kind: "generic", built: buildRegionLanding(regionCombo, plans), plans };
139	  }
140	
141	  const combo = findCombo(slug);
142	  if (combo) {
143	    const plans = await loadVpsPlans();
144	    return { kind: "generic", built: buildLanding(combo, plans), plans };
145	  }
146	
147	  const generalCombo = findGeneralLocationCombo(slug);
148	  if (generalCombo) {
149	    const plans = await loadVpsPlans();
150	    return { kind: "generic", built: buildGeneralLocationLanding(generalCombo, plans), plans };
151	  }
152	
153	  const gameCombo = findGameLocationCombo(slug);
154	  if (gameCombo) {
155	    const { rows, cards } = await loadGamePlans(gameCombo.family);
156	    const built = buildGameLocationLanding(gameCombo, rows);
157	    const previewGame = buildGameLocationPreviewGame(gameCombo, cards);
158	    return { kind: "game-family", built, plans: cards, gameFamily: built.gameFamily, productName: built.productName, previewGame };
159	  }
160	
161	  return undefined;
162	}
163	
164	export async function generateMetadata({
165	  params,
166	}: {
167	  params: Promise<{ slug: string }>;
168	}): Promise<Metadata> {
169	  const { slug } = await params;
170	  const resolved = await resolve(slug);
171	  if (!resolved) return {};
172	  const { built } = resolved;
173	
174	  const url = `${APP_URL}/${slug}`;
175	
176	  return {
177	    title: built.metaTitle,
178	    description: built.metaDescription,
179	    alternates: { canonical: `/${slug}` },
180	    openGraph: {
181	      type: "article",
182	      title: built.ogTitle,
183	      description: built.ogDescription,
184	      url,
185	    },
186	    twitter: {
187	      card: "summary_large_image",
188	      title: built.ogTitle,
189	      description: built.ogDescription,
190	    },
191	  };
192	}
193	
194	export default async function LocationServiceLandingPage({
195	  params,
196	}: {
197	  params: Promise<{ slug: string }>;
198	}) {
199	  const { slug } = await params;
200	  const resolved = await resolve(slug);
201	  if (!resolved) notFound();
202	  const { built, plans } = resolved;
203	
204	  const url = `${APP_URL}/${slug}`;
205	
206	  // BreadcrumbList — helps Google render the Home › <Page> trail and reinforces
207	  // the page's place in the site. FAQ + Product JSON-LD are emitted below,
208	  // either by UseCaseLanding (generic pages) or directly here (game-family
209	  // combos rendered through GameLandingCombined instead), so all three rich
210	  // results are covered either way.
211	  const breadcrumb = {
212	    "@context": "https://schema.org",
213	    "@type": "BreadcrumbList",
214	    itemListElement: [
215	      { "@type": "ListItem", position: 1, name: "Home", item: APP_URL },
216	      { "@type": "ListItem", position: 2, name: built.breadcrumbName, item: url },
217	    ],
218	  };
219	
220	  // Game×location combos render through the SAME flagship template as the
221	  // ~40 hand-built per-game pages (GameLandingCombined) instead of the
222	  // generic UseCaseLanding/PricingGrid path — see gameLocationLandings.ts's
223	  // buildGameLocationPreviewGame. Falls through to the generic branch below
224	  // if `family` somehow has no PREVIEW_GAMES fixture (shouldn't happen).
225	  if (resolved.kind === "game-family" && resolved.previewGame) {
226	    const { built: gameBuilt, previewGame, productName } = resolved;
227	    return (
228	      <>
229	        <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumb) }} />
230	        <FaqJsonLd items={gameBuilt.content.faq} />
231	        <ProductOffersJsonLd
232	          name={productName}
233	          description={gameBuilt.content.sub}
234	          url={url}
235	          offers={resolved.plans.map((p) => ({ name: p.name, price: p.priceCents / 100 }))}
236	        />
237	
238	        <GameLandingCombined game={previewGame} reviewBadges={<ReviewBadges />} />
239	
240	        {/* FAQ + related — carried over from the same content the ~40 static
241	         * per-game pages ship below GameLandingCombined (e.g. rust-server-
242	         * hosting/page.tsx), reusing this combo's own honest, location-aware
243	         * copy from buildGameLocationLanding rather than duplicating it. */}
244	        <Section tone="base" size="md">
245	          <SectionTitle eyebrow="FAQ" title="Questions, answered" />
246	          <div className="mx-auto mt-10 max-w-3xl space-y-3">
247	            {gameBuilt.content.faq.map((f) => (
248	              <details key={f.q} className="card group">
249	                <summary className="cursor-pointer list-none font-medium text-white marker:content-none">
250	                  <span className="flex items-center justify-between gap-4">
251	                    {f.q}
252	                    <span className="text-slate-500 transition-transform group-open:rotate-45">+</span>
253	                  </span>
254	                </summary>
255	                <p className="mt-3 text-sm leading-relaxed text-slate-400">{f.a}</p>
256	              </details>
257	            ))}
258	          </div>
259	        </Section>
260	
261	        {gameBuilt.content.related && gameBuilt.content.related.length > 0 && (
262	          <Section tone="base" size="sm">
263	            <div className="mx-auto flex max-w-3xl flex-wrap items-center justify-center gap-2">
264	              <span className="text-xs font-semibold uppercase tracking-wider text-slate-500">Related</span>
265	              {gameBuilt.content.related.map((r) => (
266	                <Link
267	                  key={r.href}
268	                  href={r.href}
269	                  className="rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 text-sm text-slate-300 transition-colors hover:border-white/20 hover:text-white"
270	                >
271	                  {r.label}
272	                </Link>
273	              ))}
274	            </div>
275	          </Section>
276	        )}
277	      </>
278	    );
279	  }
280	
281	  return (
282	    <>
283	      <script
284	        type="application/ld+json"
285	        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumb) }}
286	      />
287	      <UseCaseLanding
288	        content={built.content}
289	        plans={plans as PlanCard[]}
290	        service={resolved.kind === "game-family" ? "game" : "vps"}
291	        gameFamily={resolved.kind === "game-family" ? resolved.gameFamily : undefined}
292	        productName={resolved.kind === "game-family" ? resolved.productName : undefined}
293	        pageUrl={url}
294	      />
295	    </>
296	  );
297	}
