204	function pingHtml(c: Ctx) {
205	  const r = c.region!, info = r.info!, m = MAPS[info.map], dc = r.coords;
206	  if (!dc) throw new Error(`nxm games: no REGION_COORDS for ${r.code}`);
207	  const proj = (lat: number, lon: number) => [((lon - m.lon[0]) / (m.lon[1] - m.lon[0])) * m.W, ((m.lat[1] - lat) / (m.lat[1] - m.lat[0])) * m.H];
208	  const [dx, dy] = proj(dc.lat, dc.lon);
209	  const BANDS: [number, string, string][] = [[1000, "Under 1,000 km", "#3FD89A"], [2500, "Under 2,500 km", "#3EDCF2"], [Infinity, "Farther", "#9B8CFF"]];
210	  let arcs = "", labels = "", lst = "";
211	  info.cities.forEach((city, n) => {
212	    const [x, y] = proj(city.lat, city.lon), k = `c${n}`, km = distanceKm(dc, city), band = BANDS.find(([lim]) => km < lim)!, tc = band[2];
213	    const mx = (dx + x) / 2, my = (dy + y) / 2, dist = Math.hypot(x - dx, y - dy);
214	    let nx = -(y - dy) / (dist || 1), ny = (x - dx) / (dist || 1);
215	    if (ny > 0) { nx = -nx; ny = -ny; }
216	    const cx = mx + nx * dist * 0.28, cy = my + ny * dist * 0.28;
217	    arcs += `<path id="a${n}" class="arc" data-k="${k}" style="--tc:${tc}" d="M${dx.toFixed(0)} ${dy.toFixed(0)} Q${cx.toFixed(0)} ${cy.toFixed(0)} ${x.toFixed(0)} ${y.toFixed(0)}"/><circle class="pkt" r="5"><animateMotion dur="${(1.6 + dist / 900).toFixed(1)}s" repeatCount="indefinite" begin="${(n * 0.35).toFixed(2)}s"><mpath href="#a${n}"/></animateMotion></circle><circle class="cd" style="--tc:${tc}" cx="${x.toFixed(0)}" cy="${y.toFixed(0)}" r="9"/>`;
218	    labels += `<span class="gl ${city.anchor}" data-k="${k}" style="left:${((x / m.W) * 100).toFixed(2)}%;top:${((y / m.H) * 100).toFixed(2)}%;--tc:${tc}"><span class="flag flag-${city.cc}"></span>${esc(city.name)}</span>`;
219	    lst += `<li data-k="${k}" style="--tc:${tc}"><span class="flag flag-${city.cc}"></span>${esc(city.name)}<em>${(km < 1000 ? Math.round(km / 10) * 10 : Math.round(km / 50) * 50).toLocaleString("en-US")} km</em></li>`;
220	  });
221	  labels += `<span class="gl dc b" style="left:${((dx / m.W) * 100).toFixed(2)}%;top:${((dy / m.H) * 100).toFixed(2)}%">${r.cc ? `<span class="flag flag-${r.cc}"></span>` : ""}${esc(r.city)}</span>`;
222	  return `<section class="section gmp" id="ping" aria-labelledby="pg-title"><div class="container gmp-in">
223	  <div class="gmp-map"><div class="gmap" id="gmap" style="aspect-ratio:${m.W}/${m.H}" aria-hidden="true"><img src="/nxm/games/maps/${info.map}.webp" alt="" width="${m.W}" height="${m.H}"><svg viewBox="0 0 ${m.W} ${m.H}" preserveAspectRatio="xMidYMid meet"><defs><radialGradient id="dcg"><stop offset="0" stop-color="${info.acc}" stop-opacity=".55"/><stop offset="1" stop-color="${info.acc}" stop-opacity="0"/></radialGradient></defs><circle cx="${dx.toFixed(0)}" cy="${dy.toFixed(0)}" r="180" fill="url(#dcg)"/>${arcs}<circle class="dcp" cx="${dx.toFixed(0)}" cy="${dy.toFixed(0)}" r="14"/><circle class="dcp d2" cx="${dx.toFixed(0)}" cy="${dy.toFixed(0)}" r="14"/><circle class="dc0" cx="${dx.toFixed(0)}" cy="${dy.toFixed(0)}" r="11"/></svg>${labels}</div></div>
224	  <div><h2 class="h2" id="pg-title">Where your players connect from</h2><p class="lede">How far the cities your players live in are from ${esc(r.city)}. Closer usually means lower ping; real latency also depends on each player’s connection. Hover a city to see its route.</p><div class="lat au-glass glat" id="lat"><div class="lat-h"><b>Distance to your players</b><span class="lat-leg"><i class="t1"></i>${BANDS[0][1]}<i class="t2"></i>${BANDS[1][1]}<i class="t3"></i>${BANDS[2][1]}</span></div><ul>${lst}</ul></div></div>
225	</div></section>`;
226	}
