65	/** Active tiers grouped by family (one query), cheapest first. */
66	export async function tiersByFamily(regions: string[], family?: string): Promise<Map<string, RealTier[]>> {
67	  const rows = await db.gamePlan.findMany({
68	    where: { active: true, ...(family ? { gameFamily: family } : {}) },
69	    orderBy: [{ ramMB: "asc" }, { sortOrder: "asc" }],
70	  });
71	  const out = new Map<string, RealTier[]>();
72	  for (const g of rows) out.set(g.gameFamily, [...(out.get(g.gameFamily) ?? []), toTier(g, regions)]);
