76	function toTier(g: GamePlan, regions: string[]): RealTier {
77	  const perMonth = (c: number) => (g.termMonths > 1 ? c / g.termMonths : c);
78	  const intro = planIntroMonthlyCents(g);
79	  return {
80	    id: g.id, name: g.name, ram: gb(g.ramMB), cpu: g.cpuCores, disk: g.diskGB, slots: g.slots,
81	    p: perMonth(g.priceCents) / 100, i: intro == null ? null : perMonth(intro) / 100,
82	    is: intro == null ? "" : introSpan(planIntroTermMonths(g)), featured: g.featured,
83	    href: Object.fromEntries(regions.map((r) => [r, deployHref({ service: "game", gameFamily: g.gameFamily, gamePlanId: g.id, region: r })])),
84	  };
85	}
