91	    where: { active: true },
92	    select: { gameFamily: true, priceCents: true, introPriceCents: true, introTermMonths: true, termMonths: true, slots: true, ramMB: true, id: true, featured: true },
93	  });
94	  const by = new Map<string, typeof rows>();
95	  for (const r of rows) by.set(r.gameFamily, [...(by.get(r.gameFamily) ?? []), r]);
96	  return GAME_FAMILIES.filter((f) => by.has(f)).map((f) => {
97	    const ts = by.get(f)!;
