101	    });
102	    const slots = ts.map((t) => t.slots).filter((s): s is number => s != null);
103	    return {
104	      family: f as string, name: gameName(f), genres: gameGenres(f), route: gameRoute(f),
105	      fromCents: Math.round(Math.min(...monthly)), maxSlots: slots.length ? Math.max(...slots) : null, tiers: ts.length,
106	    };
107	  });
108	}
