153	export function distanceKm(a: { lat: number; lon: number }, b: { lat: number; lon: number }) {
154	  const D = Math.PI / 180, dLat = (b.lat - a.lat) * D, dLon = (b.lon - a.lon) * D;
155	  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * D) * Math.cos(b.lat * D) * Math.sin(dLon / 2) ** 2;
156	  return 2 * 6371 * Math.asin(Math.sqrt(h));
157	}
