import fs from 'fs';
import { feature } from 'topojson-client';
import { geoContains } from 'd3-geo';
const topo = JSON.parse(fs.readFileSync('node_modules/world-atlas/land-110m.json','utf8'));
const land = feature(topo, topo.objects.land);
const W = 256, H = 128; // equirectangular grid
const bytes = new Uint8Array(W*H/8);
let count=0;
for (let y=0;y<H;y++){
  const lat = 90 - (y+0.5)*180/H;
  for (let x=0;x<W;x++){
    const lon = -180 + (x+0.5)*360/W;
    if (geoContains(land,[lon,lat])) { const i=y*W+x; bytes[i>>3] |= (1<<(i&7)); count++; }
  }
}
fs.writeFileSync('mask.b64', Buffer.from(bytes).toString('base64'));
console.log('land cells', count, 'b64 len', Buffer.from(bytes).toString('base64').length);
// quick ascii preview at 1/4
let s='';
for (let y=0;y<H;y+=4){ for(let x=0;x<W;x+=2){const i=y*W+x; s+= (bytes[i>>3]>>(i&7))&1?'#':' ';} s+='\n';}
console.log(s);
