/** Country flag + local time zone per location slug (LocationDef, RegionDef
 *  and GameLocationDef share one slug space for these purposes). Multi-zone
 *  countries/aggregates have no zone: the page shows no local clock there. */
export const PLACE: Record<string, { cc: string; tz?: string }> = {
  // city matrix (lib/marketing/locationLandings.ts LOCATIONS)
  singapore: { cc: "sg", tz: "Asia/Singapore" }, germany: { cc: "de", tz: "Europe/Berlin" }, london: { cc: "gb", tz: "Europe/London" },
  frankfurt: { cc: "de", tz: "Europe/Berlin" }, amsterdam: { cc: "nl", tz: "Europe/Amsterdam" }, paris: { cc: "fr", tz: "Europe/Paris" },
  "new-york": { cc: "us", tz: "America/New_York" }, toronto: { cc: "ca", tz: "America/Toronto" }, "los-angeles": { cc: "us", tz: "America/Los_Angeles" },
  sydney: { cc: "au", tz: "Australia/Sydney" }, tokyo: { cc: "jp", tz: "Asia/Tokyo" }, mumbai: { cc: "in", tz: "Asia/Kolkata" },
  dallas: { cc: "us", tz: "America/Chicago" }, miami: { cc: "us", tz: "America/New_York" }, chicago: { cc: "us", tz: "America/Chicago" },
  "hong-kong": { cc: "hk", tz: "Asia/Hong_Kong" }, seoul: { cc: "kr", tz: "Asia/Seoul" }, dubai: { cc: "ae", tz: "Asia/Dubai" },
  "sao-paulo": { cc: "br", tz: "America/Sao_Paulo" },
  // region tier (REGIONS)
  usa: { cc: "us" }, europe: { cc: "" }, "asia-pacific": { cc: "" },
  // game x location / general tables (GAME_LOCATIONS; flags come from the live table itself)
  "southeast-asia": { cc: "" }, "south-korea": { cc: "kr", tz: "Asia/Seoul" }, japan: { cc: "jp", tz: "Asia/Tokyo" },
  malaysia: { cc: "my", tz: "Asia/Kuala_Lumpur" }, indonesia: { cc: "id" }, "united-kingdom": { cc: "gb", tz: "Europe/London" },
  india: { cc: "in", tz: "Asia/Kolkata" }, "united-states": { cc: "us" }, "north-america": { cc: "" }, canada: { cc: "ca" },
  netherlands: { cc: "nl", tz: "Europe/Amsterdam" }, australia: { cc: "au" },
};

export type Point = { name: string; cc: string; lat: number; lon: number };

export function point(name: string): Point {
  const c = CITY[name];
  if (!c) throw new Error(`nxm location: no coordinates for "${name}" (app/nxm/_data/location-geo.ts CITY)`);
  return { name, lat: c[0], lon: c[1], cc: c[2] };
}

/** Great-circle distance, km. */
export function km(a: { lat: number; lon: number }, b: { lat: number; lon: number }) {
  const D = Math.PI / 180, dLat = (b.lat - a.lat) * D, dLon = (b.lon - a.lon) * D;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * D) * Math.cos(b.lat * D) * Math.sin(dLon / 2) ** 2;
  return 2 * 6371 * Math.asin(Math.sqrt(h));
}

/** "830 km" / "10,850 km" (rounded like the game x location pages). */
export const kmLabel = (d: number) => `${(d < 1000 ? Math.round(d / 10) * 10 : Math.round(d / 50) * 50).toLocaleString("en-US")} km`;

/** Map crops: the design's two regional maps (assets/maps/maps.json, copied to
 *  public/nxm/games/maps by the game port) and a dotted world map drawn at
 *  port time from the design's own land mask (tools/nxm/wire/location_landing.py
 *  — keep these bounds in sync with WORLD there). */
export const LOC_MAPS = {
  apac: { src: "/nxm/games/maps/apac.webp", W: 1600, H: 1468, lon: [64, 160], lat: [-46, 42] },
  eu: { src: "/nxm/games/maps/eu.webp", W: 1600, H: 1520, lon: [-14, 33], lat: [35, 64] },
  world: { src: "/nxm/loc/world.webp", W: 1600, H: 634, lon: [-135, 145], lat: [-45, 66] },
} as const;
export type MapKey = keyof typeof LOC_MAPS;

export function project(m: MapKey, lat: number, lon: number): [number, number] {
  const c = LOC_MAPS[m];
  return [((lon - c.lon[0]) / (c.lon[1] - c.lon[0])) * c.W, ((c.lat[1] - lat) / (c.lat[1] - c.lat[0])) * c.H];
}
export function inMap(m: MapKey, lat: number, lon: number, pad = 0.04) {
  const [x, y] = project(m, lat, lon), c = LOC_MAPS[m];
  return x >= c.W * pad && x <= c.W * (1 - pad) && y >= c.H * pad && y <= c.H * (1 - pad);
}

