import "server-only";
import fs from "node:fs";
import path from "node:path";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { deployHref } from "@/lib/deploy-intent";
import { planIntroMonthlyCents, planIntroTermMonths } from "@/lib/intro-pricing";
import { CUSTOMER_REGION_LABELS, REGION_LABELS } from "@/lib/node-regions";
import {
  LOCATIONS_BY_SLUG, SERVICES, buildLanding, buildRegionLanding, findCombo, findRegionCombo, isNearRealDatacenter,
  type BuiltLanding, type Combo, type LandingPlan, type RegionCombo, type ServiceDef, type ServiceKey,
} from "@/lib/marketing/locationLandings";
import {
  buildGameLocationPreviewGame, buildGeneralLocationLanding, findGameLocationCombo, findGeneralLocationCombo,
  type GameLocationCombo, type GeneralLocationCombo,
} from "@/lib/marketing/gameLocationLandings";
import GAME_ROUTE_ROWS from "../../../tools/nxm/routes/minecraft-server-hosting.json";
import GAME_LOC_ROWS from "../../../tools/nxm/routes/minecraft-server-hosting-singapore.json";
import { SEO } from "../_seo/registry";
import { btn } from "./cards";
import { esc, introSpan, nxmHref, productLd, usd, type NxmLoad } from "./lib";
import { hostingPromoActive, supportLine } from "./products-common";
import { cityArt, deployRegions, gameArt, REGION_INFO, sellableGames, tiersByFamily, type DeployRegion } from "./games-lib";
import { LOC_MAPS, PLACE, inMap, km, kmLabel, point, project, type MapKey, type Point } from "./location-geo";

/**
 * THE location template: every generated "(location) (service)" landing the
 * live site serves from app/(marketing)/[slug] (region tier, city matrix,
 * general per-location pages, game x location matrix) plus the five
 * hand-routed Singapore landers, served under /nxm by app/nxm/[slug].
 *
 * - WHICH pages exist, and every word of their copy (titles, H1, intro, why,
 *   steps, FAQ, related links, the honesty framing per `presence`), comes from
 *   the live builders in lib/marketing/locationLandings.ts and
 *   lib/marketing/gameLocationLandings.ts — so the new site says exactly what
 *   the live pages say and never claims a datacenter or latency Nxeon doesn't
 *   have. Unknown slugs 404.
 * - Prices/plans: db.plan (VPS-shaped services), db.hostingPlan (web),
 *   db.gamePlan (game servers) at request time; the builders' "from $X" is
 *   fed the same rows. Empty tables throw (the builders would otherwise fall
 *   back to a hardcoded "$6.49").
 * - Regions: enabled db.node rows. The live copy states Nxeon runs exactly
 *   two datacenters (Singapore, Falkenstein/Germany); if the enabled set ever
 *   differs, every page here throws until the copy is updated (fail closed).
 * - The map/distance panel shows straight-line km to the nearest enabled
 *   datacenter (lib/node-regions.ts REGION_COORDS), never a latency figure.
 * - Game x location combos render through the game x location template
 *   instead (./location-game.ts), like the live page renders them through the
 *   flagship game template.
 */

// ── which page a slug is ────────────────────────────────────────────────────
/** Live static pages that render a location combo (app/(marketing)/singapore-*):
 *  same builder, same combo, served here by the same template.
 *  (/singapore-vps-hosting has its own design-ported page.) */
const SG_LANDERS: Record<string, ServiceKey> = {
  "singapore-web-hosting": "web",
  "singapore-reseller-hosting": "reseller",
  "singapore-forex-vps-hosting": "forex",
  "singapore-dedicated-server-hosting": "dedicated",
  "singapore-game-server-hosting": "game",
};

export type Resolved =
  | { kind: "city"; combo: Combo }
  | { kind: "region"; combo: RegionCombo }
  | { kind: "general"; combo: GeneralLocationCombo }
  | { kind: "game"; combo: GameLocationCombo };

/** Same lookup order as app/(marketing)/[slug]/page.tsx. */
export function resolveSlug(slug: string): Resolved | null {
  if (SG_LANDERS[slug]) {
    const location = LOCATIONS_BY_SLUG.get("singapore")!;
    const service = SERVICES.find((s) => s.key === SG_LANDERS[slug])!;
    return { kind: "city", combo: { location, service, slug } };
  }
  const r = findRegionCombo(slug);
  if (r) return { kind: "region", combo: r };
  const c = findCombo(slug);
  if (c) return { kind: "city", combo: c };
  const g = findGeneralLocationCombo(slug);
  if (g) return { kind: "general", combo: g };
  const gl = findGameLocationCombo(slug);
  if (gl) return { kind: "game", combo: gl };
  return null;
}

// ── links: a route the new site serves stays inside /nxm ─────────────────────
const PORTED = new Set<string>([
  ...Object.keys(SEO),
  ...(GAME_ROUTE_ROWS as { route: string }[]).map((r) => r.route),
  ...(GAME_LOC_ROWS as { route: string }[]).map((r) => r.route),
  "/servers", "/game-servers/directory",
]);
export function link(route: string) {
  const p = route.split(/[?#]/)[0];
  return PORTED.has(p) || (/^\/[a-z0-9-]+$/.test(p) && resolveSlug(p.slice(1))) ? nxmHref(route) : route;
}

// ── regions ─────────────────────────────────────────────────────────────────
/** The regions the live copy names ("two real datacenters — Singapore and
 *  Falkenstein, Germany"). */
const COPY_REGIONS = ["fsn1", "sgp1"];
export async function copyRegions(): Promise<DeployRegion[]> {
  const regions = await deployRegions();
  const codes = regions.map((r) => r.code).sort();
  if (codes.join(",") !== COPY_REGIONS.join(",")) {
    throw new Error(`nxm location: enabled regions [${codes}] differ from the regions the live location copy names [${COPY_REGIONS}] — update lib/marketing/*Landings.ts first`);
  }
  for (const r of regions) if (!r.coords) throw new Error(`nxm location: no REGION_COORDS for ${r.code}`);
  return regions;
}
/** "Singapore", "Falkenstein, Germany" */
export const dcName = (r: DeployRegion) => {
  const city = (REGION_LABELS[r.code] ?? r.label).split(",")[0].trim();
  const country = CUSTOMER_REGION_LABELS[r.code] ?? r.label;
  return city === country ? city : `${city}, ${country}`;
};
const DC_ACC: Record<string, string> = { sgp1: "#3EDCF2", fsn1: "#9B8CFF" };
const accOf = (r: DeployRegion | null) => (r ? DC_ACC[r.code] ?? REGION_INFO[r.code]?.acc ?? "#6F8DFF" : "#6F8DFF");

// ── small markup helpers ────────────────────────────────────────────────────
const CSS_FLAGS = new Set(["au", "ca", "de", "fr", "gb", "hk", "in", "jp", "nl", "sg", "us", "at", "cz", "id", "my", "ph", "pl", "se", "th"]);
const pngFlags = new Map<string, boolean>();
const hasPng = (cc: string) => {
  if (!pngFlags.has(cc)) pngFlags.set(cc, fs.existsSync(path.join(process.cwd(), "public", "flags", `${cc}.png`)));
  return pngFlags.get(cc)!;
};
/** The design's round flag (flag-icons SVGs in the page CSS), else the site's
 *  own /flags PNG, else a neutral disc. */
export function flag(cc: string, sm = false) {
  const c = `flag${sm ? " flag-sm" : ""}`;
  if (!cc) return `<span class="${c} flag-none" aria-hidden="true"></span>`;
  if (CSS_FLAGS.has(cc)) return `<span class="${c} flag-${cc}"></span>`;
  if (hasPng(cc)) return `<span class="${c}" style="background-image:url(/flags/${cc}.png)"></span>`;
  return `<span class="${c} flag-none" aria-hidden="true"></span>`;
}
const I = (n: string) => `<span data-au-icon="${n}" data-grad></span>`;
const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);
const list = (xs: string[]) => (xs.length <= 1 ? xs.join("") : `${xs.slice(0, -1).join(", ")} and ${xs[xs.length - 1]}`);
const gbOf = (mb: number) => { const g = mb / 1024; return `${g % 1 ? g.toFixed(1) : g} GB`; };

// ── the map + distance panel (the design's location hero) ───────────────────
const BANDS: [number, string, string][] = [[1000, "Under 1,000 km", "#3FD89A"], [2500, "Under 2,500 km", "#3EDCF2"], [Infinity, "Farther", "#9B8CFF"]];
type Placed = Point & { dc: DeployRegion; d: number };

function nearestDc(p: { lat: number; lon: number }, regions: DeployRegion[]) {
  let best = regions[0], bd = Infinity;
  for (const r of regions) { const d = km(p, r.coords!); if (d < bd) { bd = d; best = r; } }
  return { dc: best, d: bd };
}

/** The design's `.gmap` (image + animated arcs + labels) for these places: a
 *  regional crop when the place and its pinned datacenter fit one, else the
 *  dotted world map with both datacenters. */
function mapHtml(pts: Placed[], regions: DeployRegion[], pinned: DeployRegion | null) {
  const crop: MapKey | null = pinned && pts.length
    ? (["apac", "eu"] as MapKey[]).find((m) => inMap(m, pinned.coords!.lat, pinned.coords!.lon) && inMap(m, pts[0].lat, pts[0].lon)) ?? null
    : null;
  const m: MapKey = crop ?? "world";
  const M = LOC_MAPS[m];
  const dcs = crop ? [pinned!] : regions;
  const drawn = pts.filter((p) => inMap(m, p.lat, p.lon, 0.01) && dcs.includes(p.dc));
  const taken: [number, number][] = [];
  const free = (x: number, y: number, r: number) => taken.every(([a, b]) => Math.hypot(a - x, b - y) > r);
  let defs = "", glow = "", arcs = "", labels = "", dots = "";
  for (const dc of dcs) {
    const [dx, dy] = project(m, dc.coords!.lat, dc.coords!.lon), acc = accOf(dc), id = `dcg-${dc.code}`;
    defs += `<radialGradient id="${id}"><stop offset="0" stop-color="${acc}" stop-opacity=".55"/><stop offset="1" stop-color="${acc}" stop-opacity="0"/></radialGradient>`;
    glow += `<circle cx="${dx.toFixed(0)}" cy="${dy.toFixed(0)}" r="${m === "world" ? 90 : 180}" fill="url(#${id})"/>`;
    dots += `<circle class="dcp" style="--acc:${acc}" cx="${dx.toFixed(0)}" cy="${dy.toFixed(0)}" r="${m === "world" ? 9 : 14}"/><circle class="dcp d2" style="--acc:${acc}" cx="${dx.toFixed(0)}" cy="${dy.toFixed(0)}" r="${m === "world" ? 9 : 14}"/><circle class="dc0" style="--acc:${acc}" cx="${dx.toFixed(0)}" cy="${dy.toFixed(0)}" r="${m === "world" ? 7 : 11}"/>`;
    labels += `<span class="gl dc b" style="left:${((dx / M.W) * 100).toFixed(2)}%;top:${((dy / M.H) * 100).toFixed(2)}%;--acc:${acc}">${flag(dc.cc)}${esc(dcName(dc).split(",")[0])}</span>`;
    taken.push([dx, dy]);
  }
  drawn.forEach((p) => {
    const n = pts.indexOf(p), k = `c${n}`;
    const [x, y] = project(m, p.lat, p.lon), [dx, dy] = project(m, p.dc.coords!.lat, p.dc.coords!.lon);
    const tc = BANDS.find(([lim]) => p.d < lim)![2];
    const mx = (dx + x) / 2, my = (dy + y) / 2, dist = Math.hypot(x - dx, y - dy);
    let nx = -(y - dy) / (dist || 1), ny = (x - dx) / (dist || 1);
    if (ny > 0) { nx = -nx; ny = -ny; }
    const cx = mx + nx * dist * 0.28, cy = my + ny * dist * 0.28;
    arcs += `<path id="a${n}" class="arc" data-k="${k}" style="--tc:${tc}" d="M${dx.toFixed(0)} ${dy.toFixed(0)} Q${cx.toFixed(0)} ${cy.toFixed(0)} ${x.toFixed(0)} ${y.toFixed(0)}"/><circle class="pkt" r="${m === "world" ? 4 : 5}"><animateMotion dur="${(1.6 + dist / 900).toFixed(1)}s" repeatCount="indefinite" begin="${(n * 0.35).toFixed(2)}s"><mpath href="#a${n}"/></animateMotion></circle><circle class="cd" style="--tc:${tc}" cx="${x.toFixed(0)}" cy="${y.toFixed(0)}" r="${m === "world" ? 7 : 9}"/>`;
    // labels only where they don't collide (close cities keep their dot + list entry)
    if (free(x, y, m === "world" ? 70 : 110)) {
      const ax = x - dx, ay = y - dy;
      const anchor = Math.abs(ax) > Math.abs(ay) ? (ax > 0 ? "r" : "l") : ay > 0 ? "b" : "t";
      labels += `<span class="gl ${anchor}" data-k="${k}" style="left:${((x / M.W) * 100).toFixed(2)}%;top:${((y / M.H) * 100).toFixed(2)}%;--tc:${tc}">${flag(p.cc)}${esc(p.name)}</span>`;
      taken.push([x, y]);
    }
  });
  return {
    world: m === "world",
    html: `<div class="gmap${m === "world" ? " gmap--w" : ""}" id="gmap" style="aspect-ratio:${M.W}/${M.H}" aria-hidden="true"><img src="${M.src}" alt="" width="${M.W}" height="${M.H}"><svg viewBox="0 0 ${M.W} ${M.H}" preserveAspectRatio="xMidYMid meet"><defs>${defs}</defs>${glow}${arcs}${dots}</svg>${labels}</div>`,
  };
}

function latHtml(pts: Placed[], pinned: DeployRegion | null) {
  const items = pts.slice(0, 8).map((p, n) => {
    const tc = BANDS.find(([lim]) => p.d < lim)![2];
    return `<li data-k="c${n}" style="--tc:${tc}">${flag(p.cc)}${esc(p.name)}<em>${kmLabel(p.d)} · ${esc(p.dc.label)}</em></li>`;
  }).join("");
  const title = pinned ? `Distance to our ${esc(pinned.label)} datacenter` : "Distance to our nearest datacenter";
  return `<div class="lat au-glass" id="lat"><div class="lat-h"><b>${title}</b><span class="lat-leg"><i class="t1"></i>${BANDS[0][1]}<i class="t2"></i>${BANDS[1][1]}<i class="t3"></i>${BANDS[2][1]}</span></div><ul>${items}</ul><p class="lat-f">Straight-line distance. Closer usually means lower ping; real latency depends on the route and each connection.</p></div>`;
}

// ── the place a page targets ────────────────────────────────────────────────
type Place = {
  slug: string; name: string; cc: string; tz?: string;
  presence: "datacenter" | "network" | "market";
  names: string[];
  /** the live copy allows "near/low ping" framing for this place */ near: boolean;
  /** the lib's own nearest real region for GAME_LOCATIONS (game/general tables) */ libRegion?: string;
};

function placeOf(r: Exclude<Resolved, { kind: "game" }>): Place {
  if (r.kind === "city") {
    const l = r.combo.location;
    return { slug: l.slug, name: l.city, cc: PLACE[l.slug]?.cc ?? "", tz: PLACE[l.slug]?.tz, presence: l.presence,
      names: [l.city, ...l.nearby], near: l.presence === "datacenter" || isNearRealDatacenter(l) };
  }
  if (r.kind === "region") {
    const g = r.combo.region;
    const cities = g.locationSlugs.map((s) => LOCATIONS_BY_SLUG.get(s)!).filter(Boolean);
    return { slug: g.slug, name: g.shortLabel, cc: PLACE[g.slug]?.cc ?? "", presence: g.presence,
      names: cities.map((c) => c.city), near: g.slug === "europe" };
  }
  const l = r.combo.location;
  const pg = buildGameLocationPreviewGame({ location: l, family: "minecraft", slug: r.combo.slug }, []);
  return { slug: l.slug, name: l.name, cc: l.flag || PLACE[l.slug]?.cc || "", tz: PLACE[l.slug]?.tz, presence: l.presence,
    names: l.nearby, near: l.presence !== "market", libRegion: pg?.deployRegion };
}

/** Places with coordinates (a name the live table lists without an entry in
 *  location-geo.ts throws), the datacenter's own city dropped (the map marks
 *  it), each with its nearest enabled datacenter. */
function placed(names: string[], regions: DeployRegion[]): Placed[] {
  const out: Placed[] = [];
  for (const n of names) {
    if (n === "Germany") continue; // the "germany" city entry is the Falkenstein datacenter itself
    const p = point(n);
    const { dc, d } = nearestDc(p, regions);
    if (d < 60 || out.some((o) => o.name === p.name)) continue;
    out.push({ ...p, dc, d });
  }
  return out;
}

// ── plans ───────────────────────────────────────────────────────────────────
const VPS_LIKE: ServiceKey[] = ["vps", "dedicated", "forex", "reseller"];
/** The sizing the page's own spec note recommends (lib copy: "Standard (4 GB)
 *  is a strong start", "Starter (2 GB)" for a single EA, "Pro (8 GB)" for
 *  dedicated-grade work) — highlighted on the card whose real RAM matches. */
const REC_RAM: Partial<Record<ServiceKey, number>> = { vps: 4096, forex: 2048, reseller: 4096, dedicated: 8192 };
const VPS_CARD: Record<string, { k: string; bullets: (region: string) => string[] }> = {
  vps: { k: "Cloud VPS", bullets: (rg) => ["Full root and dedicated IPv4", rg, "Always-on DDoS filtering", "Ready in about 47 seconds"] },
  forex: { k: "Trading VPS", bullets: (rg) => ["Dedicated IPv4", "99.9% uptime SLA", rg, "Always-on DDoS filtering"] },
  reseller: { k: "Reseller VPS", bullets: (rg) => ["Built-in multi-site panel", "Full root + IPv4", rg, "No markup, no approval"] },
  dedicated: { k: "Dedicated resources", bullets: (rg) => ["Dedicated CPU + RAM", "Full root + IPv4", rg, "Always-on DDoS filtering"] },
};

function priceBlock(regularCents: number, introCents: number | null, span: string) {
  return introCents != null
    ? `<p class="pp"><b>${usd(introCents)}</b><s>${usd(regularCents)}</s><span>${esc(span)}</span></p><p class="then">Then ${usd(regularCents)} a month</p>`
    : `<p class="pp"><b>${usd(regularCents)}</b><span>/month</span></p><p class="then">&nbsp;</p>`;
}
const bulletList = (xs: string[]) => `<ul>${xs.map((x) => `<li>${esc(x)}</li>`).join("")}</ul>`;

type Offer = { name: string; price: number };
type PlansOut = { landing: LandingPlan[]; html: string; offers: Offer[]; stats: { from: string; fromWhat: string; count: string; countH: string; countP: string } };

async function vpsPlansOut(svc: ServiceKey, region: DeployRegion | null, regionBullet: string): Promise<PlansOut> {
  const rows = await db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } });
  if (!rows.length) throw new Error("nxm location: no active VPS plans");
  const def = VPS_CARD[svc] ?? VPS_CARD.vps;
  const rec = REC_RAM[svc] ?? REC_RAM.vps!;
  const cards = rows.map((p) => {
    const intro = planIntroMonthlyCents(p);
    const pop = p.ramMB === rec;
    const href = deployHref({ service: "vps", planId: p.id, termMonths: 1, region: region?.code });
    return `<article class="au-card lp${pop ? " pop" : ""}">${pop ? `<span class="tag">Recommended</span>` : ""}<small class="k">${esc(def.k)}, ${esc(p.name)}</small><h3>${gbOf(p.ramMB)} RAM</h3><p class="lsp">${p.cpuCores} vCPU, ${p.diskGB} GB NVMe, ${p.bandwidthTB} TB transfer</p>${priceBlock(p.priceCents, intro, introSpan(intro == null ? null : planIntroTermMonths(p)))}${bulletList(def.bullets(regionBullet))}${btn(pop, href, region ? `Deploy in ${region.label}` : `Deploy ${p.name}`)}</article>`;
  });
  const cheapest = rows.reduce((a, b) => ((planIntroMonthlyCents(a) ?? a.priceCents) <= (planIntroMonthlyCents(b) ?? b.priceCents) ? a : b));
  const cIntro = planIntroMonthlyCents(cheapest);
  return {
    landing: rows,
    html: `<div class="lpl n${Math.min(rows.length, 4)}">${cards.join("")}</div>`,
    offers: rows.map((p) => ({ name: `${def.k} ${p.name}`, price: (planIntroMonthlyCents(p) ?? p.priceCents) / 100 })),
    stats: {
      from: usd(cIntro ?? cheapest.priceCents),
      fromWhat: `${cheapest.name} plan${cIntro != null ? `, ${introSpan(planIntroTermMonths(cheapest))}, then ${usd(cheapest.priceCents)}` : ""}`,
      count: String(rows.length), countH: `${def.k} plans`,
      countP: `From ${gbOf(Math.min(...rows.map((p) => p.ramMB)))} to ${gbOf(Math.max(...rows.map((p) => p.ramMB)))} RAM, resize any time.`,
    },
  };
}

async function webPlansOut(): Promise<PlansOut> {
  const [rows, promo] = await Promise.all([
    db.hostingPlan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
    hostingPromoActive(),
  ]);
  if (!rows.length) throw new Error("nxm location: no active hosting plans");
  const cards = rows.map((p) => {
    const pop = p.featured;
    const sites = `${p.maxSites} site${p.maxSites === 1 ? "" : "s"}`;
    const mail = p.mailboxes < 0 ? "unlimited mailboxes" : `${p.mailboxes} mailbox${p.mailboxes === 1 ? "" : "es"}`;
    const bullets = ["Free SSL, issued automatically", "One-click WordPress", `Email on your domain (${mail})`, ...(p.freeMigration ? ["Free migration from your old host"] : [])];
    const href = deployHref({ service: "hosting", hostingPlanId: p.id });
    return `<article class="au-card lp${pop ? " pop" : ""}">${pop ? `<span class="tag">Most popular</span>` : ""}<small class="k">Web hosting</small><h3>${esc(p.name)}</h3><p class="lsp">${p.diskGB} GB SSD, ${sites}, ${p.maxDatabases} database${p.maxDatabases === 1 ? "" : "s"}</p>${priceBlock(p.priceCents, null, "")}<p class="then lp-promo">${promo ? "First month free" : "&nbsp;"}</p>${bulletList(bullets)}${btn(pop, href, `Get ${p.name}`)}</article>`;
  });
  const cheapest = rows.reduce((a, b) => (a.priceCents <= b.priceCents ? a : b));
  const landing: LandingPlan[] = rows.map((p) => ({ id: p.id, name: p.name, cpuCores: 1, ramMB: 0, diskGB: p.diskGB, bandwidthTB: p.bandwidthTB, priceCents: p.priceCents, storageTier: "shared" }));
  return {
    landing,
    html: `<div class="lpl n${Math.min(rows.length, 4)}">${cards.join("")}</div>`,
    offers: rows.map((p) => ({ name: `Web hosting ${p.name}`, price: p.priceCents / 100 })),
    stats: {
      from: usd(cheapest.priceCents), fromWhat: `${cheapest.name} plan, per month${promo ? ", first month free" : ""}`,
      count: String(rows.length), countH: "Web hosting plans",
      countP: `From ${Math.min(...rows.map((p) => p.diskGB))} GB to ${Math.max(...rows.map((p) => p.diskGB))} GB storage, upgrade any time.`,
    },
  };
}

/** The games the live copy names first ("Minecraft, Rust, Valheim, Palworld,
 *  CS2 or an ARK cluster"), then the rest of the sellable catalogue. */
const COPY_GAMES = ["minecraft", "rust", "valheim", "palworld", "cs2", "ark"];
async function gamePlansOut(regions: DeployRegion[], region: DeployRegion | null, regionBullet: string): Promise<PlansOut & { total: number }> {
  const [games, byFam, rows] = await Promise.all([
    sellableGames(),
    tiersByFamily(regions.map((r) => r.code)),
    db.gamePlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
  ]);
  if (!games.length || !rows.length) throw new Error("nxm location: no sellable game plans");
  const pick = [...COPY_GAMES.map((f) => games.find((g) => g.family === f)).filter((g): g is (typeof games)[number] => !!g),
    ...games.filter((g) => !COPY_GAMES.includes(g.family))].slice(0, 6);
  const offers: Offer[] = [];
  const cards = pick.map((g) => {
    const tiers = byFam.get(g.family) ?? [];
    const t = [...tiers].sort((a, b) => (a.i ?? a.p) - (b.i ?? b.p))[0];
    if (!t) throw new Error(`nxm location: no tiers for ${g.family}`);
    offers.push({ name: `${g.name} ${t.ram} GB`, price: t.i ?? t.p });
    const art = gameArt(g.family).cover;
    const ramR = `${Math.min(...tiers.map((x) => x.ram))}–${Math.max(...tiers.map((x) => x.ram))} GB`;
    const href = deployHref({ service: "game", gameFamily: g.family, region: region?.code });
    const page = g.route ? `<a class="lp-more" href="${esc(link(g.route))}">${esc(g.name)} hosting →</a>` : "";
    return `<article class="au-card lp lp-g">${art ? `<img class="lp-art" src="${esc(art)}" alt="" width="60" height="80" loading="lazy">` : ""}<small class="k">Game server</small><h3>${esc(g.name)}</h3><p class="lsp">${ramR}${g.maxSlots ? `, up to ${g.maxSlots} player slots` : ""}</p>${priceBlock(Math.round(t.p * 100), t.i == null ? null : Math.round(t.i * 100), t.is)}${bulletList(["One-click game installs", "Full file + FTP access", regionBullet, "Always-on DDoS protection"])}${btn(false, href, `Deploy ${g.name}`)}${page}</article>`;
  });
  const monthly = (p: (typeof rows)[number]) => (planIntroMonthlyCents(p) ?? p.priceCents) / Math.max(1, p.termMonths);
  const cheapest = rows.reduce((a, b) => (monthly(a) <= monthly(b) ? a : b));
  // the builders read price/intro off each row: per-month, like checkout shows it
  const landing = rows.map((p) => ({
    id: p.id, name: p.name, cpuCores: p.cpuCores, ramMB: p.ramMB, diskGB: p.diskGB, bandwidthTB: 1, storageTier: "nvme",
    priceCents: Math.round(p.priceCents / Math.max(1, p.termMonths)),
    introPriceCents: p.introPriceCents == null ? null : Math.round(p.introPriceCents / Math.max(1, p.termMonths)), introTermMonths: p.introTermMonths,
  })) as LandingPlan[];
  const cIntro = planIntroMonthlyCents(cheapest);
  return {
    landing, offers, total: games.length,
    html: `<div class="lpl n3">${cards.join("")}</div>`,
    stats: {
      from: usd(Math.round(monthly(cheapest))),
      fromWhat: `${cheapest.name}${cIntro != null ? `, ${introSpan(planIntroTermMonths(cheapest))}` : ", per month"}`,
      count: String(games.length), countH: "Games to choose from",
      countP: "Each with its own sizes and player slots, on one account.",
    },
  };
}

// ── the page ────────────────────────────────────────────────────────────────
type Ctx = {
  slug: string; r: Exclude<Resolved, { kind: "game" }>; svc: ServiceDef; place: Place; regions: DeployRegion[];
  pinned: DeployRegion | null; pts: Placed[]; plans: PlansOut & { total?: number }; built: BuiltLanding;
};

async function context(slug: string): Promise<Ctx> {
  const r = resolveSlug(slug);
  if (!r || r.kind === "game") notFound();
  const regions = await copyRegions();
  const svcKey: ServiceKey = r.kind === "general" ? r.combo.service : r.combo.service.key;
  const svc = SERVICES.find((s) => s.key === svcKey)!;
  const place = placeOf(r);
  const pts = placed(place.names, regions);
  // Deploy links pre-select a region only where the live copy itself frames
  // the place as near one (datacenter / near-datacenter / the lib's own
  // nearest region); everywhere else the customer picks at checkout.
  let pinned: DeployRegion | null = null;
  if (place.libRegion) pinned = regions.find((x) => x.code === place.libRegion) ?? null;
  else if (place.near && pts.length) pinned = pts[0].dc;
  else if (place.near && place.slug === "germany") pinned = regions.find((x) => x.code === "fsn1") ?? null;
  const regionBullet = pinned ? `${pinned.label} region` : `${list(regions.map((x) => x.label))}, your pick`;
  const plans = VPS_LIKE.includes(svcKey) ? await vpsPlansOut(svcKey, pinned, regionBullet)
    : svcKey === "web" ? await webPlansOut()
    : await gamePlansOut(regions, pinned, regionBullet);
  const built = r.kind === "city" ? buildLanding(r.combo, plans.landing)
    : r.kind === "region" ? buildRegionLanding(r.combo, plans.landing)
    : buildGeneralLocationLanding(r.combo, plans.landing);
  return { slug, r, svc, place, regions, pinned, pts, plans, built };
}

const NOUN: Record<ServiceKey, string> = { vps: "server", dedicated: "server", forex: "trading VPS", reseller: "client sites", web: "site", game: "game server" };
const WHY_ICON: [RegExp, string][] = [
  [/ddos|firewall/i, "shield"], [/nvme|zfs|storage/i, "database"], [/deploy|setup|second|instant/i, "bolt"],
  [/resize|scale|grow/i, "chart"], [/backup|snapshot|uptime|24\/7|runs/i, "backup"], [/ipv4|\bip\b/i, "globe"],
  [/root|stack|rules|panel/i, "terminal"], [/cpu|ram|resources|power/i, "cpu"], [/mod|file/i, "gear"],
  [/php|mysql|wordpress|ssl|email|vps/i, "cloud"], [/markup|priced|bill|client/i, "card"],
  [/ping|latency|aimed|built|tuned|sized|hub|market|region|community|games?/i, "globe"],
];
const iconFor = (t: string) => WHY_ICON.find(([re]) => re.test(t))?.[1] ?? "spark";

export async function load(p: Record<string, string>): Promise<NxmLoad & { template: "location" | "game" }> {
  const r = resolveSlug(p.slug);
  if (!r) notFound();
  if (r.kind === "game") {
    const { gameLocationPage } = await import("./location-game");
    return { template: "game", ...(await gameLocationPage(p.slug, r.combo)) };
  }
  const c = await context(p.slug);
  const { built, svc, place, pinned, pts, regions, plans } = c;
  const { content } = built;
  const route = `/${c.slug}`;
  const svcKey = svc.key;
  const map = mapHtml(pts, regions, pinned);
  const where = pinned ? pinned : null;

  // hero
  const badges = `<span class="au-chip">${place.cc ? flag(place.cc, true) : I("globe")}${esc(content.eyebrow.replace(/^\S+\s(?=\S)/u, (m) => (/\p{Regional_Indicator}/u.test(m) ? "" : m)))}</span>`
    + (place.tz ? `<span class="au-chip lc-clock"><i class="d"></i>${esc(place.name)} <b id="lc-time">--:--</b></span>` : "");
  const deployMain = svcKey === "web" ? { href: link("/web-hosting"), label: "See web hosting" }
    : svcKey === "game" ? { href: "#plans", label: "Pick your game" }
    : { href: deployHref({ service: "vps", region: where?.code }), label: where ? `Deploy in ${where.label}` : "Deploy a server" };
  const ctas = btn(true, deployMain.href, deployMain.label)
    + `<a class="nxm-glassbtn" href="${svcKey === "game" ? esc(link("/game-servers")) : "#plans"}"><span class="nxm-bt">${svcKey === "game" ? "All game servers" : "See plans"}</span></a>`;

  // "where it runs" band: the page's own honest answer + real numbers
  const locFaq = content.faq[0];
  const dcStat = place.presence === "datacenter" && where
    ? `<article class="au-card"><b>${esc(dcName(where).split(",")[0])}</b><h3>Our own datacenter</h3><p>Deploy links on this page pre-select the ${esc(where.label)} region.</p></article>`
    : pts.length > 1 && c.r.kind === "region"
      ? `<article class="au-card"><b>${kmLabel(Math.min(...pts.map((x) => x.d)))}+</b><h3>From these ${pts.length} cities</h3><p>Straight-line distance from each to its nearest Nxeon datacenter (${list(pts.map((x) => `${x.name} ${kmLabel(x.d)}`))}).</p></article>`
      : pts[0]
        ? `<article class="au-card"><b>${kmLabel(pts[0].d)}</b><h3>${esc(pts[0].name)} to ${esc(pts[0].dc.label)}</h3><p>Straight-line distance to the nearest Nxeon datacenter. Real ping depends on the route.</p></article>`
        : "";
  const stats = dcStat
    + `<article class="au-card"><b>${regions.length}</b><h3>Real datacenters</h3><p>${esc(list(regions.map(dcName)))}. You choose one at checkout.</p></article>`
    + `<article class="au-card"><b>${esc(plans.stats.from)}</b><h3>Starting price</h3><p>${esc(plans.stats.fromWhat)}.</p></article>`
    + `<article class="au-card"><b>${esc(plans.stats.count)}</b><h3>${esc(plans.stats.countH)}</h3><p>${esc(plans.stats.countP)}</p></article>`;
  const bandImg = where ? cityArt(where.code) : null;

  // why / steps / faq / related
  const why = content.why.map((w, k) => `<article class="au-card au-hov"><span class="au-tile">${I(iconFor(w.title))}</span><h3><span class="n">${String(k + 1).padStart(2, "0")}</span>${esc(w.title)}</h3><p>${esc(w.body)}</p></article>`).join("");
  const steps = content.steps.map((s, k) => `<li class="au-card"><span class="n">${String(k + 1).padStart(2, "0")}</span><h3>${esc(s.title)}</h3><p>${esc(s.body)}</p></li>`).join("");
  const faq = content.faq.map((f, n) => `<details${n === 0 ? " open" : ""}><summary>${esc(f.q)}</summary><p>${esc(f.a)}</p></details>`).join("");
  const related = (content.related ?? []).map((x) => `<a class="lrel-a" href="${esc(link(x.href))}">${esc(x.label)}<span aria-hidden="true">→</span></a>`).join("");

  // our datacenters (the design's "other region" card, one per real region)
  const others = regions.filter((x) => x.code !== where?.code);
  const siblingSlug = (x: DeployRegion) => `/${x.code === "sgp1" ? "singapore" : "germany"}-${svc.urlPart}`;
  const lots = others.map((x) => {
    const img = cityArt(x.code);
    return `<a class="lot" href="${esc(link(siblingSlug(x)))}"${img ? ` style="--img:url(${img})"` : ""}><div><span class="au-chip">${flag(x.cc, true)}${where ? "Also available" : "Nxeon datacenter"}</span><h2>${esc(svc.label)} in ${esc(x.label)}</h2><p>${esc(REGION_INFO[x.code]?.blurb ?? dcName(x))}. Same account, same plans.</p></div><span class="lot-go" aria-hidden="true">→</span></a>`;
  }).join("");

  const finalH = svcKey === "game" ? `${cap(content.eyebrow.replace(/^\P{L}+/u, ""))}, online in minutes.`
    : svcKey === "web" ? `${cap(content.eyebrow.replace(/^\P{L}+/u, ""))}, ready when your domain is.`
    : `${cap(content.eyebrow.replace(/^\P{L}+/u, ""))}, live in about 47 seconds.`;
  const finalCtas = btn(true, deployMain.href === "#plans" ? link("/game-servers") : deployMain.href, deployMain.href === "#plans" ? "Browse every game" : deployMain.label)
    + `<a class="nxm-glassbtn" href="${esc(link("/pricing"))}"><span class="nxm-bt">Compare pricing</span></a>`;

  return {
    template: "location",
    slots: {
      acc: accOf(where),
      "hero.cls": map.world ? "lh2--w" : "",
      "map:html": map.html,
      "badges:html": badges,
      h1a: content.title, h1b: content.highlight, sub: content.sub,
      "ctas:html": ctas,
      "lat:html": pts.length ? latHtml(pts, where) : "",
      "band.style": bandImg ? `--img:url(${bandImg})` : "",
      "band.chip:html": `${place.cc ? flag(place.cc, true) : I("globe")}${esc(place.name)}`,
      "band.h": place.presence === "datacenter" ? "A real Nxeon datacenter" : `Where your ${NOUN[svcKey]} actually runs`,
      "band.p": locFaq?.a ?? "",
      "stats:html": stats,
      "intro.h": cap(content.eyebrow.replace(/^\P{L}+/u, "")),
      "intro:html": content.intro.map((x) => `<p>${esc(x)}</p>`).join(""),
      "why.h": content.whyTitle,
      "why:html": why,
      "steps:html": steps,
      "plans.h": svcKey === "game" ? "Pick your game." : `Pick a size${where ? `. We’ll pin it to ${where.label}.` : "."}`,
      "plans.lede": svcKey === "game"
        ? `Real per-game pricing${where ? `, provisioned in the ${where.label} region` : `, in ${list(regions.map((x) => x.label))}`}. ${plans.total ?? ""} games in all, one account.`.replace(" .", ".")
        : svcKey === "web" ? "Real hosting-plan pricing. Free SSL and email on every plan."
        : `Real plan pricing${where ? `, provisioned in the ${where.label} region` : ""}. Intro prices apply to your first term only.`,
      "plans:html": plans.html + (svcKey === "game" ? `<div class="lpl-all">${btn(false, link("/game-servers"), `See all ${plans.total} games`)}</div>` : ""),
      spec: content.specNote,
      "faq.h": `${cap(content.eyebrow.replace(/^\P{L}+/u, ""))}, answered`,
      "faq.lede": supportLine(),
      "faq:html": faq,
      "other:html": lots ? `<div class="lots n${others.length}">${lots}</div>` : "",
      "related:html": related,
      "final.h": finalH,
      "final:html": finalCtas,
    },
    data: { tz: place.tz ?? null },
    jsonLd: [productLd(`Nxeon ${built.breadcrumbName}`, built.metaDescription, route, plans.offers)],
    crumb: built.breadcrumbName,
  };
}

export async function meta(p: Record<string, string>) {
  const r = resolveSlug(p.slug);
  if (!r) notFound();
  if (r.kind === "game") {
    const { gameLocationMeta } = await import("./location-game");
    return gameLocationMeta(p.slug, r.combo);
  }
  const c = await context(p.slug);
  return { title: c.built.metaTitle, description: c.built.metaDescription, crumb: c.built.breadcrumbName, type: "article" as const };
}

