import "server-only";
import fs from "node:fs";
import path from "node:path";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { deployHref } from "@/lib/deploy-intent";
import { planIntroMonthlyCents, planIntroTermMonths } from "@/lib/intro-pricing";
import { CUSTOMER_REGION_LABELS, REGION_LABELS } from "@/lib/node-regions";
import {
  LOCATIONS_BY_SLUG, SERVICES, buildLanding, buildRegionLanding, findCombo, findRegionCombo, isNearRealDatacenter,
  type BuiltLanding, type Combo, type LandingPlan, type RegionCombo, type ServiceDef, type ServiceKey,
} from "@/lib/marketing/locationLandings";
import {
  buildGameLocationPreviewGame, buildGeneralLocationLanding, findGameLocationCombo, findGeneralLocationCombo,
  type GameLocationCombo, type GeneralLocationCombo,
} from "@/lib/marketing/gameLocationLandings";
import GAME_ROUTE_ROWS from "../../../tools/nxm/routes/minecraft-server-hosting.json";
import GAME_LOC_ROWS from "../../../tools/nxm/routes/minecraft-server-hosting-singapore.json";
import { SEO } from "../_seo/registry";
import { btn } from "./cards";
import { esc, introSpan, nxmHref, productLd, usd, type NxmLoad } from "./lib";
import { hostingPromoActive, supportLine } from "./products-common";
import { cityArt, deployRegions, gameArt, REGION_INFO, sellableGames, tiersByFamily, type DeployRegion } from "./games-lib";
import { LOC_MAPS, PLACE, inMap, km, kmLabel, point, project, type MapKey, type Point } from "./location-geo";

/**
 * THE location template: every generated "(location) (service)" landing the
 * live site serves from app/(marketing)/[slug] (region tier, city matrix,
 * general per-location pages, game x location matrix) plus the five
 * hand-routed Singapore landers, served under /nxm by app/nxm/[slug].
 *
 * - WHICH pages exist, and every word of their copy (titles, H1, intro, why,
 *   steps, FAQ, related links, the honesty framing per `presence`), comes from
 *   the live builders in lib/marketing/locationLandings.ts and
 *   lib/marketing/gameLocationLandings.ts — so the new site says exactly what
 *   the live pages say and never claims a datacenter or latency Nxeon doesn't
 *   have. Unknown slugs 404.
 * - Prices/plans: db.plan (VPS-shaped services), db.hostingPlan (web),
 *   db.gamePlan (game servers) at request time; the builders' "from $X" is
 *   fed the same rows. Empty tables throw (the builders would otherwise fall
 *   back to a hardcoded "$6.49").
 * - Regions: enabled db.node rows. The live copy states Nxeon runs exactly
 *   two datacenters (Singapore, Falkenstein/Germany); if the enabled set ever
 *   differs, every page here throws until the copy is updated (fail closed).
 * - The map/distance panel shows straight-line km to the nearest enabled
 *   datacenter (lib/node-regions.ts REGION_COORDS), never a latency figure.
 * - Game x location combos render through the game x location template
 *   instead (./location-game.ts), like the live page renders them through the
 *   flagship game template.
 */

// ── which page a slug is ────────────────────────────────────────────────────
/** Live static pages that render a location combo (app/(marketing)/singapore-*):
 *  same builder, same combo, served here by the same template.
 *  (/singapore-vps-hosting has its own design-ported page.) */
const SG_LANDERS: Record<string, ServiceKey> = {
  "singapore-web-hosting": "web",
  "singapore-reseller-hosting": "reseller",
  "singapore-forex-vps-hosting": "forex",
  "singapore-dedicated-server-hosting": "dedicated",
  "singapore-game-server-hosting": "game",
};

export type Resolved =
  | { kind: "city"; combo: Combo }
  | { kind: "region"; combo: RegionCombo }
  | { kind: "general"; combo: GeneralLocationCombo }
  | { kind: "game"; combo: GameLocationCombo };

/** Same lookup order as app/(marketing)/[slug]/page.tsx. */
export function resolveSlug(slug: string): Resolved | null {
  if (SG_LANDERS[slug]) {
    const location = LOCATIONS_BY_SLUG.get("singapore")!;
    const service = SERVICES.find((s) => s.key === SG_LANDERS[slug])!;
    return { kind: "city", combo: { location, service, slug } };
  }
  const r = findRegionCombo(slug);
  if (r) return { kind: "region", combo: r };
  const c = findCombo(slug);
  if (c) return { kind: "city", combo: c };
  const g = findGeneralLocationCombo(slug);
  if (g) return { kind: "general", combo: g };
  const gl = findGameLocationCombo(slug);
  if (gl) return { kind: "game", combo: gl };
  return null;
}

// ── links: a route the new site serves stays inside /nxm ─────────────────────
const PORTED = new Set<string>([
  ...Object.keys(SEO),
  ...(GAME_ROUTE_ROWS as { route: string }[]).map((r) => r.route),
  ...(GAME_LOC_ROWS as { route: string }[]).map((r) => r.route),
  "/servers", "/game-servers/directory",
]);
export function link(route: string) {
  const p = route.split(/[?#]/)[0];
  return PORTED.has(p) || (/^\/[a-z0-9-]+$/.test(p) && resolveSlug(p.slice(1))) ? nxmHref(route) : route;
}

// ── regions ─────────────────────────────────────────────────────────────────
/** The regions the live copy names ("two real datacenters — Singapore and
 *  Falkenstein, Germany"). */
const COPY_REGIONS = ["fsn1", "sgp1"];
export async function copyRegions(): Promise<DeployRegion[]> {
  const regions = await deployRegions();
  const codes = regions.map((r) => r.code).sort();
  if (codes.join(",") !== COPY_REGIONS.join(",")) {
    throw new Error(`nxm location: enabled regions [${codes}] differ from the regions the live location copy names [${COPY_REGIONS}] — update lib/marketing/*Landings.ts first`);
  }
  for (const r of regions) if (!r.coords) throw new Error(`nxm location: no REGION_COORDS for ${r.code}`);
  return regions;
}
/** "Singapore", "Falkenstein, Germany" */
export const dcName = (r: DeployRegion) => {
  const city = (REGION_LABELS[r.code] ?? r.label).split(",")[0].trim();
  const country = CUSTOMER_REGION_LABELS[r.code] ?? r.label;
  return city === country ? city : `${city}, ${country}`;
};
const DC_ACC: Record<string, string> = { sgp1: "#3EDCF2", fsn1: "#9B8CFF" };
const accOf = (r: DeployRegion | null) => (r ? DC_ACC[r.code] ?? REGION_INFO[r.code]?.acc ?? "#6F8DFF" : "#6F8DFF");

// ── small markup helpers ────────────────────────────────────────────────────
const CSS_FLAGS = new Set(["au", "ca", "de", "fr", "gb", "hk", "in", "jp", "nl", "sg", "us", "at", "cz", "id", "my", "ph", "pl", "se", "th"]);
const pngFlags = new Map<string, boolean>();
const hasPng = (cc: string) => {
  if (!pngFlags.has(cc)) pngFlags.set(cc, fs.existsSync(path.join(process.cwd(), "public", "flags", `${cc}.png`)));
  return pngFlags.get(cc)!;
};
/** The design's round flag (flag-icons SVGs in the page CSS), else the site's
 *  own /flags PNG, else a neutral disc. */
export function flag(cc: string, sm = false) {
  const c = `flag${sm ? " flag-sm" : ""}`;
  if (!cc) return `<span class="${c} flag-none" aria-hidden="true"></span>`;
  if (CSS_FLAGS.has(cc)) return `<span class="${c} flag-${cc}"></span>`;
  if (hasPng(cc)) return `<span class="${c}" style="background-image:url(/flags/${cc}.png)"></span>`;
  return `<span class="${c} flag-none" aria-hidden="true"></span>`;
}
const I = (n: string) => `<span data-au-icon="${n}" data-grad></span>`;
const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);
const list = (xs: string[]) => (xs.length <= 1 ? xs.join("") : `${xs.slice(0, -1).join(", ")} and ${xs[xs.length - 1]}`);
const gbOf = (mb: number) => { const g = mb / 1024; return `${g % 1 ? g.toFixed(1) : g} GB`; };

// ── the map + distance panel (the design's location hero) ───────────────────
const BANDS: [number, string, string][] = [[1000, "Under 1,000 km", "#3FD89A"], [2500, "Under 2,500 km", "#3EDCF2"], [Infinity, "Farther", "#9B8CFF"]];
type Placed = Point & { dc: DeployRegion; d: number };

function nearestDc(p: { lat: number; lon: number }, regions: DeployRegion[]) {
  let best = regions[0], bd = Infinity;
  for (const r of regions) { const d = km(p, r.coords!); if (d < bd) { bd = d; best = r; } }
  return { dc: best, d: bd };
}

/** The design's `.gmap` (image + animated arcs + labels) for these places: a
 *  regional crop when the place and its pinned datacenter fit one, else the
 *  dotted world map with both datacenters. */
function mapHtml(pts: Placed[], regions: DeployRegion[], pinned: DeployRegion | null) {
  const crop: MapKey | null = pinned && pts.length
    ? (["apac", "eu"] as MapKey[]).find((m) => inMap(m, pinned.coords!.lat, pinned.coords!.lon) && inMap(m, pts[0].lat, pts[0].lon)) ?? null
    : null;
  const m: MapKey = crop ?? "world";
  const M = LOC_MAPS[m];
  const dcs = crop ? [pinned!] : regions;
  const drawn = pts.filter((p) => inMap(m, p.lat, p.lon, 0.01) && dcs.includes(p.dc));
  const taken: [number, number][] = [];
  const free = (x: number, y: number, r: number) => taken.every(([a, b]) => Math.hypot(a - x, b - y) > r);
  let defs = "", glow = "", arcs = "", labels = "", dots = "";
  for (const dc of dcs) {
    const [dx, dy] = project(m, dc.coords!.lat, dc.coords!.lon), acc = accOf(dc), id = `dcg-${dc.code}`;
    defs += `<radialGradient id="${id}"><stop offset="0" stop-color="${acc}" stop-opacity=".55"/><stop offset="1" stop-color="${acc}" stop-opacity="0"/></radialGradient>`;
    glow += `<circle cx="${dx.toFixed(0)}" cy="${dy.toFixed(0)}" r="${m === "world" ? 90 : 180}" fill="url(#${id})"/>`;
    dots += `<circle class="dcp" style="--acc:${acc}" cx="${dx.toFixed(0)}" cy="${dy.toFixed(0)}" r="${m === "world" ? 9 : 14}"/><circle class="dcp d2" style="--acc:${acc}" cx="${dx.toFixed(0)}" cy="${dy.toFixed(0)}" r="${m === "world" ? 9 : 14}"/><circle class="dc0" style="--acc:${acc}" cx="${dx.toFixed(0)}" cy="${dy.toFixed(0)}" r="${m === "world" ? 7 : 11}"/>`;
    labels += `<span class="gl dc b" style="left:${((dx / M.W) * 100).toFixed(2)}%;top:${((dy / M.H) * 100).toFixed(2)}%;--acc:${acc}">${flag(dc.cc)}${esc(dcName(dc).split(",")[0])}</span>`;
    taken.push([dx, dy]);
  }
  drawn.forEach((p) => {
    const n = pts.indexOf(p), k = `c${n}`;
    const [x, y] = project(m, p.lat, p.lon), [dx, dy] = project(m, p.dc.coords!.lat, p.dc.coords!.lon);
    const tc = BANDS.find(([lim]) => p.d < lim)![2];
    const mx = (dx + x) / 2, my = (dy + y) / 2, dist = Math.hypot(x - dx, y - dy);
    let nx = -(y - dy) / (dist || 1), ny = (x - dx) / (dist || 1);
    if (ny > 0) { nx = -nx; ny = -ny; }
    const cx = mx + nx * dist * 0.28, cy = my + ny * dist * 0.28;
    arcs += `<path id="a${n}" class="arc" data-k="${k}" style="--tc:${tc}" d="M${dx.toFixed(0)} ${dy.toFixed(0)} Q${cx.toFixed(0)} ${cy.toFixed(0)} ${x.toFixed(0)} ${y.toFixed(0)}"/><circle class="pkt" r="${m === "world" ? 4 : 5}"><animateMotion dur="${(1.6 + dist / 900).toFixed(1)}s" repeatCount="indefinite" begin="${(n * 0.35).toFixed(2)}s"><mpath href="#a${n}"/></animateMotion></circle><circle class="cd" style="--tc:${tc}" cx="${x.toFixed(0)}" cy="${y.toFixed(0)}" r="${m === "world" ? 7 : 9}"/>`;
    // labels only where they don't collide (close cities keep their dot + list entry)
    if (free(x, y, m === "world" ? 70 : 110)) {
      const ax = x - dx, ay = y - dy;
      const anchor = Math.abs(ax) > Math.abs(ay) ? (ax > 0 ? "r" : "l") : ay > 0 ? "b" : "t";
      labels += `<span class="gl ${anchor}" data-k="${k}" style="left:${((x / M.W) * 100).toFixed(2)}%;top:${((y / M.H) * 100).toFixed(2)}%;--tc:${tc}">${flag(p.cc)}${esc(p.name)}</span>`;
      taken.push([x, y]);
    }
  });
  return {
    world: m === "world",
    html: `<div class="gmap${m === "world" ? " gmap--w" : ""}" id="gmap" style="aspect-ratio:${M.W}/${M.H}" aria-hidden="true"><img src="${M.src}" alt="" width="${M.W}" height="${M.H}"><svg viewBox="0 0 ${M.W} ${M.H}" preserveAspectRatio="xMidYMid meet"><defs>${defs}</defs>${glow}${arcs}${dots}</svg>${labels}</div>`,
  };
}

function latHtml(pts: Placed[], pinned: DeployRegion | null) {
  const items = pts.slice(0, 8).map((p, n) => {
    const tc = BANDS.find(([lim]) => p.d < lim)![2];
    return `<li data-k="c${n}" style="--tc:${tc}">${flag(p.cc)}${esc(p.name)}<em>${kmLabel(p.d)} · ${esc(p.dc.label)}</em></li>`;
  }).join("");
  const title = pinned ? `Distance to our ${esc(pinned.label)} datacenter` : "Distance to our nearest datacenter";
  return `<div class="lat au-glass" id="lat"><div class="lat-h"><b>${title}</b><span class="lat-leg"><i class="t1"></i>${BANDS[0][1]}<i class="t2"></i>${BANDS[1][1]}<i class="t3"></i>${BANDS[2][1]}</span></div><ul>${items}</ul><p class="lat-f">Straight-line distance. Closer usually means lower ping; real latency depends on the route and each connection.</p></div>`;
}

// ── the place a page targets ────────────────────────────────────────────────
type Place = {
  slug: string; name: string; cc: string; tz?: string;
  presence: "datacenter" | "network" | "market";
  names: string[];
  /** the live copy allows "near/low ping" framing for this place */ near: boolean;
  /** the lib's own nearest real region for GAME_LOCATIONS (game/general tables) */ libRegion?: string;
};

function placeOf(r: Exclude<Resolved, { kind: "game" }>): Place {
  if (r.kind === "city") {
    const l = r.combo.location;
    return { slug: l.slug, name: l.city, cc: PLACE[l.slug]?.cc ?? "", tz: PLACE[l.slug]?.tz, presence: l.presence,
      names: [l.city, ...l.nearby], near: l.presence === "datacenter" || isNearRealDatacenter(l) };
  }
  if (r.kind === "region") {
    const g = r.combo.region;
    const cities = g.locationSlugs.map((s) => LOCATIONS_BY_SLUG.get(s)!).filter(Boolean);
    return { slug: g.slug, name: g.shortLabel, cc: PLACE[g.slug]?.cc ?? "", presence: g.presence,
      names: cities.map((c) => c.city), near: g.slug === "europe" };
  }
  const l = r.combo.location;
  const pg = buildGameLocationPreviewGame({ location: l, family: "minecraft", slug: r.combo.slug }, []);
  return { slug: l.slug, name: l.name, cc: l.flag || PLACE[l.slug]?.cc || "", tz: PLACE[l.slug]?.tz, presence: l.presence,
    names: l.nearby, near: l.presence !== "market", libRegion: pg?.deployRegion };
}

/** Places with coordinates (a name the live table lists without an entry in
 *  location-geo.ts throws), the datacenter's own city dropped (the map marks
 *  it), each with its nearest enabled datacenter. */
function placed(names: string[], regions: DeployRegion[]): Placed[] {
  const out: Placed[] = [];
  for (const n of names) {
    if (n === "Germany") continue; // the "germany" city entry is the Falkenstein datacenter itself
    const p = point(n);
    const { dc, d } = nearestDc(p, regions);
    if (d < 60 || out.some((o) => o.name === p.name)) continue;
    out.push({ ...p, dc, d });
  }
  return out;
}

