const bulletList = (xs: string[]) => `<ul>${xs.map((x) => `<li>${esc(x)}</li>`).join("")}</ul>`;

type Offer = { name: string; price: number };
type PlansOut = { landing: LandingPlan[]; html: string; offers: Offer[]; stats: { from: string; fromWhat: string; count: string; countH: string; countP: string } };

async function vpsPlansOut(svc: ServiceKey, region: DeployRegion | null, regionBullet: string): Promise<PlansOut> {
  const rows = await db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } });
  if (!rows.length) throw new Error("nxm location: no active VPS plans");
  const def = VPS_CARD[svc] ?? VPS_CARD.vps;
  const rec = REC_RAM[svc] ?? REC_RAM.vps!;
  const cards = rows.map((p) => {
    const intro = planIntroMonthlyCents(p);
    const pop = p.ramMB === rec;
    const href = deployHref({ service: "vps", planId: p.id, termMonths: 1, region: region?.code });
    return `<article class="au-card lp${pop ? " pop" : ""}">${pop ? `<span class="tag">Recommended</span>` : ""}<small class="k">${esc(def.k)}, ${esc(p.name)}</small><h3>${gbOf(p.ramMB)} RAM</h3><p class="lsp">${p.cpuCores} vCPU, ${p.diskGB} GB NVMe, ${p.bandwidthTB} TB transfer</p>${priceBlock(p.priceCents, intro, introSpan(intro == null ? null : planIntroTermMonths(p)))}${bulletList(def.bullets(regionBullet))}${btn(pop, href, region ? `Deploy in ${region.label}` : `Deploy ${p.name}`)}</article>`;
  });
  const cheapest = rows.reduce((a, b) => ((planIntroMonthlyCents(a) ?? a.priceCents) <= (planIntroMonthlyCents(b) ?? b.priceCents) ? a : b));
  const cIntro = planIntroMonthlyCents(cheapest);
  return {
    landing: rows,
    html: `<div class="lpl n${Math.min(rows.length, 4)}">${cards.join("")}</div>`,
    offers: rows.map((p) => ({ name: `${def.k} ${p.name}`, price: (planIntroMonthlyCents(p) ?? p.priceCents) / 100 })),
    stats: {
      from: usd(cIntro ?? cheapest.priceCents),
      fromWhat: `${cheapest.name} plan${cIntro != null ? `, ${introSpan(planIntroTermMonths(cheapest))}, then ${usd(cheapest.priceCents)}` : ""}`,
      count: String(rows.length), countH: `${def.k} plans`,
      countP: `From ${gbOf(Math.min(...rows.map((p) => p.ramMB)))} to ${gbOf(Math.max(...rows.map((p) => p.ramMB)))} RAM, resize any time.`,
    },
  };
}

