  [/php|mysql|wordpress|ssl|email|vps/i, "cloud"], [/markup|priced|bill|client/i, "card"],
  [/ping|latency|aimed|built|tuned|sized|hub|market|region|community|games?/i, "globe"],
];
const iconFor = (t: string) => WHY_ICON.find(([re]) => re.test(t))?.[1] ?? "spark";

export async function load(p: Record<string, string>): Promise<NxmLoad & { template: "location" | "game" }> {
  const r = resolveSlug(p.slug);
  if (!r) notFound();
  if (r.kind === "game") {
    const { gameLocationPage } = await import("./location-game");
    return { template: "game", ...(await gameLocationPage(p.slug, r.combo)) };
  }
  const c = await context(p.slug);
  const { built, svc, place, pinned, pts, regions, plans } = c;
  const { content } = built;
  const route = `/${c.slug}`;
  const svcKey = svc.key;
  const map = mapHtml(pts, regions, pinned);
  const where = pinned ? pinned : null;

  // hero
  const badges = `<span class="au-chip">${place.cc ? flag(place.cc, true) : I("globe")}${esc(content.eyebrow.replace(/^\S+\s(?=\S)/u, (m) => (/\p{Regional_Indicator}/u.test(m) ? "" : m)))}</span>`
    + (place.tz ? `<span class="au-chip lc-clock"><i class="d"></i>${esc(place.name)} <b id="lc-time">--:--</b></span>` : "");
  const deployMain = svcKey === "web" ? { href: link("/web-hosting"), label: "See web hosting" }
    : svcKey === "game" ? { href: "#plans", label: "Pick your game" }
    : { href: deployHref({ service: "vps", region: where?.code }), label: where ? `Deploy in ${where.label}` : "Deploy a server" };
  const ctas = btn(true, deployMain.href, deployMain.label)
    + `<a class="nxm-glassbtn" href="${svcKey === "game" ? esc(link("/game-servers")) : "#plans"}"><span class="nxm-bt">${svcKey === "game" ? "All game servers" : "See plans"}</span></a>`;

  // "where it runs" band: the page's own honest answer + real numbers
  const locFaq = content.faq[0];
  const dcStat = place.presence === "datacenter" && where
    ? `<article class="au-card"><b>${esc(dcName(where).split(",")[0])}</b><h3>Our own datacenter</h3><p>Deploy links on this page pre-select the ${esc(where.label)} region.</p></article>`
    : pts.length > 1 && c.r.kind === "region"
      ? `<article class="au-card"><b>${kmLabel(Math.min(...pts.map((x) => x.d)))}+</b><h3>From these ${pts.length} cities</h3><p>Straight-line distance from each to its nearest Nxeon datacenter (${list(pts.map((x) => `${x.name} ${kmLabel(x.d)}`))}).</p></article>`
      : pts[0]
        ? `<article class="au-card"><b>${kmLabel(pts[0].d)}</b><h3>${esc(pts[0].name)} to ${esc(pts[0].dc.label)}</h3><p>Straight-line distance to the nearest Nxeon datacenter. Real ping depends on the route.</p></article>`
        : "";
  const stats = dcStat
    + `<article class="au-card"><b>${regions.length}</b><h3>Real datacenters</h3><p>${esc(list(regions.map(dcName)))}. You choose one at checkout.</p></article>`
    + `<article class="au-card"><b>${esc(plans.stats.from)}</b><h3>Starting price</h3><p>${esc(plans.stats.fromWhat)}.</p></article>`
    + `<article class="au-card"><b>${esc(plans.stats.count)}</b><h3>${esc(plans.stats.countH)}</h3><p>${esc(plans.stats.countP)}</p></article>`;
  const bandImg = where ? cityArt(where.code) : null;

  // why / steps / faq / related
  const why = content.why.map((w, k) => `<article class="au-card au-hov"><span class="au-tile">${I(iconFor(w.title))}</span><h3><span class="n">${String(k + 1).padStart(2, "0")}</span>${esc(w.title)}</h3><p>${esc(w.body)}</p></article>`).join("");
  const steps = content.steps.map((s, k) => `<li class="au-card"><span class="n">${String(k + 1).padStart(2, "0")}</span><h3>${esc(s.title)}</h3><p>${esc(s.body)}</p></li>`).join("");
  const faq = content.faq.map((f, n) => `<details${n === 0 ? " open" : ""}><summary>${esc(f.q)}</summary><p>${esc(f.a)}</p></details>`).join("");
  const related = (content.related ?? []).map((x) => `<a class="lrel-a" href="${esc(link(x.href))}">${esc(x.label)}<span aria-hidden="true">→</span></a>`).join("");

  // our datacenters (the design's "other region" card, one per real region)
  const others = regions.filter((x) => x.code !== where?.code);
  const siblingSlug = (x: DeployRegion) => `/${x.code === "sgp1" ? "singapore" : "germany"}-${svc.urlPart}`;
  const lots = others.map((x) => {
    const img = cityArt(x.code);
    return `<a class="lot" href="${esc(link(siblingSlug(x)))}"${img ? ` style="--img:url(${img})"` : ""}><div><span class="au-chip">${flag(x.cc, true)}${where ? "Also available" : "Nxeon datacenter"}</span><h2>${esc(svc.label)} in ${esc(x.label)}</h2><p>${esc(REGION_INFO[x.code]?.blurb ?? dcName(x))}. Same account, same plans.</p></div><span class="lot-go" aria-hidden="true">→</span></a>`;
  }).join("");

  const finalH = svcKey === "game" ? `${cap(content.eyebrow.replace(/^\P{L}+/u, ""))}, online in minutes.`
    : svcKey === "web" ? `${cap(content.eyebrow.replace(/^\P{L}+/u, ""))}, ready when your domain is.`
    : `${cap(content.eyebrow.replace(/^\P{L}+/u, ""))}, live in about 47 seconds.`;
  const finalCtas = btn(true, deployMain.href === "#plans" ? link("/game-servers") : deployMain.href, deployMain.href === "#plans" ? "Browse every game" : deployMain.label)
    + `<a class="nxm-glassbtn" href="${esc(link("/pricing"))}"><span class="nxm-bt">Compare pricing</span></a>`;

  return {
    template: "location",
    slots: {
      acc: accOf(where),
      "hero.cls": map.world ? "lh2--w" : "",
      "map:html": map.html,
      "badges:html": badges,
      h1a: content.title, h1b: content.highlight, sub: content.sub,
      "ctas:html": ctas,
      "lat:html": pts.length ? latHtml(pts, where) : "",
      "band.style": bandImg ? `--img:url(${bandImg})` : "",
      "band.chip:html": `${place.cc ? flag(place.cc, true) : I("globe")}${esc(place.name)}`,
      "band.h": place.presence === "datacenter" ? "A real Nxeon datacenter" : `Where your ${NOUN[svcKey]} actually runs`,
      "band.p": locFaq?.a ?? "",
      "stats:html": stats,
      "intro.h": cap(content.eyebrow.replace(/^\P{L}+/u, "")),
      "intro:html": content.intro.map((x) => `<p>${esc(x)}</p>`).join(""),
      "why.h": content.whyTitle,
      "why:html": why,
      "steps:html": steps,
      "plans.h": svcKey === "game" ? "Pick your game." : `Pick a size${where ? `. We’ll pin it to ${where.label}.` : "."}`,
      "plans.lede": svcKey === "game"
        ? `Real per-game pricing${where ? `, provisioned in the ${where.label} region` : `, in ${list(regions.map((x) => x.label))}`}. ${plans.total ?? ""} games in all, one account.`.replace(" .", ".")
        : svcKey === "web" ? "Real hosting-plan pricing. Free SSL and email on every plan."
        : `Real plan pricing${where ? `, provisioned in the ${where.label} region` : ""}. Intro prices apply to your first term only.`,
      "plans:html": plans.html + (svcKey === "game" ? `<div class="lpl-all">${btn(false, link("/game-servers"), `See all ${plans.total} games`)}</div>` : ""),
      spec: content.specNote,
      "faq.h": `${cap(content.eyebrow.replace(/^\P{L}+/u, ""))}, answered`,
      "faq.lede": supportLine(),
      "faq:html": faq,
      "other:html": lots ? `<div class="lots n${others.length}">${lots}</div>` : "",
      "related:html": related,
      "final.h": finalH,
      "final:html": finalCtas,
    },
    data: { tz: place.tz ?? null },
    jsonLd: [productLd(`Nxeon ${built.breadcrumbName}`, built.metaDescription, route, plans.offers)],
    crumb: built.breadcrumbName,
  };
}

export async function meta(p: Record<string, string>) {
  const r = resolveSlug(p.slug);
  if (!r) notFound();
  if (r.kind === "game") {
    const { gameLocationMeta } = await import("./location-game");
    return gameLocationMeta(p.slug, r.combo);
  }
  const c = await context(p.slug);
  return { title: c.built.metaTitle, description: c.built.metaDescription, crumb: c.built.breadcrumbName, type: "article" as const };
}

