    const ic = other ? `<span class="gl-ic gl-ic--f">${flag(other.flag || PLACE[other.slug]?.cc || "")}</span>` : `<span class="gl-ic"><span data-au-icon="${r.href === "/pricing" ? "card" : "game"}" data-grad></span></span>`;
    const small = other ? `${other.presence === "market" ? "Served from our datacenters" : other.presence === "network" ? "Near one of our datacenters" : "Real Nxeon datacenter"}` : r.href === "/pricing" ? "Every product, live prices" : r.href === "/game-servers" ? "Every game, one account" : "Every region and plan";
    void ls;
    return `<a class="gl-reg" href="${esc(link(r.href))}">${ic}<div><b>${esc(r.label)}</b><small>${esc(small)}</small></div><span class="gl-go">→</span></a>`;
  }).join("");
  slots["more:html"] = `<section class="section" id="more" style="padding-top:0"><div class="container glinks">${cards}</div></section>`;

  const tiers = c.rows;
  const data = { ...(d.data as Record<string, unknown>), tz: PLACE[loc.slug]?.tz ?? FIRST_CITY_TZ[loc.slug] ?? (region ? (d.data as { tz?: string }).tz : null) ?? "UTC" };
  return {
    slots, data,
    jsonLd: [productLd(built.productName, built.content.sub, c.route,
      tiers.map((t) => ({ name: t.name, price: (planIntroMonthlyCents(t) ?? t.priceCents) / 100 })))],
    crumb: built.breadcrumbName,
    trail: [{ name: built.breadcrumbName, path: c.route }],
    particles: d.particles,
  };
}

export async function gameLocationMeta(slug: string, combo: GameLocationCombo) {
  const c = await context(slug, combo);
  const art = gameArt(combo.family);
  return {
    title: c.built.metaTitle, description: c.built.metaDescription, crumb: c.built.breadcrumbName, type: "article" as const,
    ...(art.hero ? { image: art.hero } : {}),
  };
}

