// Render every location slug's loader + meta (no HTTP) and check the output.
import { LANDING_SLUGS, REGION_LANDING_SLUGS } from "@/lib/marketing/locationLandings";
import { GAME_LOCATION_SLUGS, GENERAL_LOCATION_SLUGS } from "@/lib/marketing/gameLocationLandings";
import { load, meta } from "@/app/nxm/_data/location-landing";
import fs from "node:fs";
const tpl = {
  location: JSON.parse(fs.readFileSync("app/nxm/_pages/location-landing/content.ts", "utf8").match(/export const BODY_HTML = (".*");\n/)![1]),
  game: JSON.parse(fs.readFileSync("app/nxm/_pages/minecraft-server-hosting-singapore/content.ts", "utf8").match(/export const BODY_HTML = (".*");\n/)![1]),
};
const SG = ["singapore-web-hosting", "singapore-reseller-hosting", "singapore-forex-vps-hosting", "singapore-dedicated-server-hosting", "singapore-game-server-hosting"];
const only = process.argv[2];
const all = [...REGION_LANDING_SLUGS, ...LANDING_SLUGS, ...GENERAL_LOCATION_SLUGS, ...SG, ...GAME_LOCATION_SLUGS].filter((s) => !only || s.includes(only));
const bad: string[] = [];
const banned = [/under \d+ ?ms/i, /\b\d+ ?ms\b/i];
let n = 0;
const t0 = Date.now();
for (const slug of all) {
  try {
    const d = await load({ slug });
    const m = await meta({ slug });
    const html = tpl[d.template];
    const need = [...new Set([...html.matchAll(/\{\{nxm:([a-zA-Z0-9_.:-]+)\}\}/g)].map((x) => x[1]))];
    const miss = need.filter((k) => !(k in (d.slots ?? {})));
    if (miss.length) bad.push(`${slug}: missing slots ${miss.join(",")}`);
    if (!m.title || !m.description) bad.push(`${slug}: no title/description`);
    const text = Object.values(d.slots ?? {}).join(" ");
    for (const re of banned) if (re.test(text.replace(/<[^>]+>/g, " "))) bad.push(`${slug}: latency figure ${text.match(re)?.[0]}`);
    if (!d.jsonLd?.length) bad.push(`${slug}: no product JSON-LD`);
    n++;
  } catch (e) {
    bad.push(`${slug}: ${String((e as Error).message ?? e).slice(0, 160)}`);
  }
}
console.log(JSON.stringify({ checked: all.length, ok: n, bad: bad.length, secs: Math.round((Date.now() - t0) / 1000) }));
console.log(bad.slice(0, 40).join("\n"));
process.exit(0);
EOF
